"""Quality pass, System Design: thin cards get numbers and follow-ups; give-away longest answers are rebalanced;
recall questions become scenarios. Applied by apply.py."""

P = {
 116: {
  'cards': {
   't116-c1': {'body': 'Pick the part most likely to break at your numbers. For IRCTC Tatkal booking that is the 10:00 a.m. burst on a few thousand seats per train, not the login page. Or ask which part the interviewer wants. Spend 10–15 minutes deep on one area rather than shallow on five.'},
   't116-c2': {'body': 'Use: “A or B. I choose A because requirement X; the cost is Y; I’ll mitigate with Z.” For example: “Async replication, because checkout writes must finish in under 50 ms; the cost is losing a few seconds of writes on failover; payment records take a synchronous path.” It shows judgement instead of memorised answers.'},
   't116-c4': {'body': 'Avoid “always” and “never”. Say “for this read-heavy feed I’d cache with a short TTL”, not “caching is always right”. An interviewer can break an absolute with one counterexample (“even for a write-heavy ledger?”), and you spend the next five minutes retreating.'},
   't116-c5': {'body': 'Presenting one option as obviously correct with no downside. Interviewers push back until you name the cost; naming it first earns the point. Have the next answer ready too: “what breaks first if traffic grows 10×?”'},
  },
  'q': {
   't116-a1': {'choices': [('b', 'Async replication, since it is faster than sync and simpler to run'), ('a', 'Async, for fast writes; failover may lose seconds, so payments go sync'), ('c', 'Kafka, since most large companies already run it in production'), ('d', 'Either works; I would go with whatever the team knows best')],
    'correct': 'a',
    'explanation': 'It names the requirement (fast writes), the cost (seconds of writes lost on failover) and a mitigation (a synchronous path for payments). “Faster and simpler” names no cost, popularity is not a requirement, and “either works” skips the decision the interviewer asked you to make.'},
   't116-a3': {'prompt': 'Design IRCTC Tatkal booking: sales open at 10:00 a.m., a train has a few thousand seats, and requests in the first minute far exceed them. You have 15 minutes for one deep dive. Which?',
    'choices': [('d', 'The login page and its OTP flow'), ('c', 'The admin tool for adding new trains'), ('a', 'Seat inventory under the opening burst'), ('b', 'The PNR status page and its caching')],
    'correct': 'a',
    'explanation': 'A burst on a small, contended seat inventory is where the design breaks: double-booked seats or a melted database. PNR status is read-heavy but easy to cache, the admin tool has a handful of users, and login matters but is a solved problem worth one sentence.'},
   't116-a4': {'choices': [('b', 'Caching is always the right answer for reads'), ('d', 'Microservices always beat a monolith at scale'), ('a', 'For this read-heavy feed, I’d cache with a short TTL'), ('c', 'Never use SQL once traffic gets large')],
    'correct': 'a',
    'explanation': 'It scopes the claim to this workload and names a choice with a limit (a short TTL). The others are absolutes an interviewer can break with one counterexample: a write-heavy ledger where a cache adds staleness, a small team for whom a monolith is simpler, or the many large systems that run on SQL.'},
   't116-d1': {
     'choices': [('a', '“A conditional update in PostgreSQL queues writers on one hot row; at our 100/s per train that is fine, so I choose it”'),
                 ('b', '“PostgreSQL is the best database, so I always pick it for every system I design”'),
                 ('c', '“Redis scales infinitely, so I put everything in Redis and skip the database”'),
                 ('d', '“We should always use microservices, because they scale better than monoliths”')],
     'correct': 'a',
     'explanation': 'It names the cost (writers take turns on one row), puts a number on the load, and then decides. Each writer holds the row until its commit is flushed, around a millisecond and more with a synchronous replica, so one row tops out somewhere in the hundreds to low thousands of updates a second; 100/s leaves headroom, while several hundred would call for a load test or split counters. The others are absolutes with no cost: no database is best for every system, Redis does not scale without limit and is a weak sole system of record, and microservices bring network and operational costs of their own.'},
  },
 },
 117: {
  'cards': {
   't117-c1': {'body': 'Drawing boxes before knowing scale or features. Ask three or four questions first: daily users, the read/write ratio, the latency target and what is out of scope. A chat app for 50 people and one for 50 million share a name, not a design.'},
   't117-c2': {'body': 'Kafka, microservices and sharding for 1,000 users. A single database on a modest server handles thousands of indexed queries a second, far more than 1,000 users generate. Start simple, add a component when a number forces you, and say which number would.'},
   't117-c3': {'body': 'Estimating, then never using the estimate. If you computed 50K read QPS, say what it means: one cache node can serve that, you would run a few for headroom and failover, and at a 90% hit rate the database sees about 5K QPS.'},
   't117-c5': {'body': 'Long silences leave the interviewer guessing. Think aloud, check in (“should I go deeper here?”) and take hints. Interviewers often hint on purpose to see how you use help, so a hint picked up well works in your favour.'},
  },
  'q': {
   't117-a1': {'choices': [('c', 'Cassandra sharded across three regions'), ('d', 'Kubernetes with a service mesh'), ('b', 'Kafka and twelve microservices'), ('a', 'One app server and a managed database')],
    'correct': 'a',
    'explanation': '1,000 daily users is well under one request a second on average; one server and a managed database, with backups and a tested restore, carry that easily. Cross-region Cassandra, a service mesh and twelve microservices each add operational work that no number asks for.'},
   't117-a2': {'choices': [('a', 'Use it to size the cache and app servers'), ('b', 'Move on; estimation is only a warm-up phase'), ('c', 'Re-estimate it more precisely, with exact figures'), ('d', 'Ask whether 50K is right, then stop there')],
    'correct': 'a',
    'explanation': 'An estimate earns credit only when it changes the design: 50K reads a second means a cache in front of the database and several app servers. Treating it as a warm-up wastes it, more precision rarely changes a decision, and checking the number without using it stops halfway.'},
   't117-a3': {'explanation': 'Reasoning out loud lets the interviewer follow, correct or hint, and earns credit even when you are unsure. Silence hides your thinking, changing the subject looks like avoidance, and a quick unexplained pick gives them nothing to assess.'},
   't117-a5': {'choices': [('b', 'Early on, you asked about the read/write ratio'), ('d', 'Early on, you asked what is out of scope'), ('c', 'You stated your traffic assumptions aloud'), ('a', 'Halfway in, you learn it gets 10 writes a day')],
    'correct': 'a',
    'explanation': 'Learning the write rate halfway through means the first half was built on guesses, and probably sized for far more traffic. Asking about the read/write ratio and the scope, and stating your assumptions aloud, are what scoping looks like.'},
   't117-d1': {'choices': [('a', 'Overkill: a table or managed queue is enough'), ('b', 'Kafka is needed for any event-driven design'), ('c', 'Use five brokers instead, to leave room to grow'), ('d', 'Fine, because Kafka is popular and widely known')],
    'correct': 'a',
    'explanation': 'At 1–12 events a second, a database table polled by a worker, or a managed queue, is plenty, while a three-broker cluster adds brokers to run, monitor and upgrade. Nothing ties events to Kafka, more brokers make it worse, and popularity is not a requirement. Have the follow-up ready: switch when the rate reaches thousands a second, or when many consumers need to replay history.'},
  },
 },
 43: {
  'cards': {
   't43-c1': {'body': 'A coordinator asks every participant to prepare (lock and promise), then tells all to commit or all to abort. It gives atomicity across databases, but each commit costs at least two round trips plus a forced log write at every participant, participants hold locks while waiting, and if the coordinator dies after prepare they are stuck.'},
   't43-c5': {'body': 'Defaulting to 2PC across microservices. It ties every service’s availability together and holds locks across network calls. Prefer sagas unless you truly need atomic commit. Expect the follow-up “what does the user see while the saga is half done?”: show “payment pending”, not a confirmed booking.'},
  },
  'q': {
   't43-a1': {'prompt': 'Checkout uses two-phase commit across the order, payment and inventory databases. During a sale the inventory database is slow for 30 seconds. What happens to checkout?',
    'choices': [('b', 'Orders and payments commit; stock catches up later'), ('c', 'Checkout skips inventory and uses a cached count'), ('d', 'Only stock updates slow down, not payments'), ('a', 'Every checkout waits, holding locks in all three')],
    'correct': 'a',
    'explanation': 'Under 2PC nothing commits until every participant has voted, so one slow database stalls every checkout while the other two hold their locks, slowing other work on those rows too. Committing without inventory is what a saga would do, and 2PC has no cached fallback.'},
   't43-a3': {'explanation': 'Each completed step is undone by a new action, in reverse order: cancel the hotel, then the flight. There is no cross-service transaction to roll back, leaving the reservations holds rooms and seats the user did not pay for, and retrying a declined card forever never ends. Compensations must be idempotent, because they can be retried too.'},
   't43-a4': {'choices': [('c', 'The services share one database transaction'), ('a', 'A coordinator calls flight, hotel and payment, then compensates'), ('d', 'The client calls each service itself'), ('b', 'Each service reacts to the previous service’s event')],
    'correct': 'a',
    'explanation': 'Orchestration means one coordinator owns the flow: it calls each step and decides when to compensate. Services reacting to each other’s events is choreography, a shared transaction is not a saga at all, and a client calling services itself leaves compensation to an app that may close halfway.'},
  },
 },
 24: {
  'cards': {
   't24-c2': {'body': 'If the order page must show product name and seller name, a normalized schema joins three tables on every view. At 5,000 order-page views a second during a sale, copying those names into the order row makes each view a single-row read; the cost is that a seller rename must now update every one of their order rows.'},
  },
  'q': {
   't24-a1': {'choices': [('a', 'Copy product and seller names into those order rows'), ('c', 'Move all the data to a document store instead'), ('d', 'Drop the foreign keys so the joins run faster'), ('b', 'Denormalise every table in the schema at once')],
    'correct': 'a',
    'explanation': 'Fix the measured hot path and keep the rest normalised; the copies cost a little on rare renames. Moving everything to a document store, or denormalising the whole schema, is a rewrite for one query, and foreign keys are checked on writes; they do not slow down reads that join.'},
   't24-a2': {'explanation': 'With 10M copies, one seller rename updates every row that seller has, possibly millions, so it belongs in a background job. Reads need fewer joins, not more, and ACID guarantees and indexing are unaffected.'},
   't24-a3': {'prompt': 'A wallet app shows the user’s balance on 6 different screens. Which data should stay in one normalised place?',
    'choices': [('c', 'The display name on a cached profile card'), ('a', 'The balance used to approve payments'), ('b', 'The merchant name on past transactions'), ('d', 'The product name printed on old invoices')],
    'correct': 'a',
    'explanation': 'The balance decides whether a payment goes through, so two copies that disagree mean approving money that is not there; keep one authoritative row, updated in a transaction, and have the screens read it. Merchant names on past transactions and product names on invoices are snapshots that should not change, and a cached display name can be a little stale.'},
   't24-d1': {'choices': [('a', 'The order must keep the address it went to'), ('b', 'SQL does not allow joining orders and customers'), ('c', 'It makes editing a saved address much faster'), ('d', 'It removes the need for a customers table')],
    'correct': 'a',
    'explanation': 'It is a snapshot of a historical fact: the parcel went to that address even if the profile changes later, so it never needs syncing. SQL joins those tables fine, editing a saved address is unaffected, and customers still need their own table.'},
  },
 },
 71: {
  'cards': {
   't71-c4': {'body': 'Cursors need a unique, ordered key. created_at alone can tie: at lunch peak a food-delivery feed may get 40 orders in the same second, and a cursor on the timestamp alone skips or repeats the ones on the boundary. Use (created_at, id), with an index on that pair.'},
  },
  'q': {
   't71-a1': {'choices': [('a', 'It reads and discards 100,000 rows first'), ('c', 'The response holds 100,000 rows'), ('d', 'It locks the table while paging through'), ('b', 'OFFSET stops the index being used')],
    'correct': 'a',
    'explanation': 'The database still reads and throws away 100,000 rows before returning 20, so each deeper page costs more. The response is still 20 rows, OFFSET takes no table lock, and an index can still supply the order; it just cannot skip ahead by a count.'},
   't71-a2': {'choices': [('d', 'The new posts appended at the bottom of the feed'), ('a', 'Repeats, as earlier items shift down a page'), ('b', 'No change, since each page is fixed'), ('c', 'An error once the offsets go stale')],
    'correct': 'a',
    'explanation': 'With newest-first offsets, each new post pushes everything down one place, so the last items of page 1 reappear at the top of page 2. New posts are not appended at the bottom, pages are not fixed, and offsets do not raise errors; they just point at different rows.'},
   't71-a3': {'prompt': 'A feed pages with WHERE (created_at, id) < cursor, newest first, 20 at a time. Which index makes each page a single seek?',
    'choices': [('b', 'Two indexes: one on created_at, one on id'), ('a', 'One composite index on (created_at, id)'), ('c', 'One index on id alone'), ('d', 'No index; the cursor already skips rows')],
    'correct': 'a',
    'explanation': 'A composite index on (created_at, id) lets the database seek straight to the cursor and read the next 20 entries in order. Two separate indexes cannot give that order in one seek, an index on id alone ignores the time order, and without an index every page scans and sorts the table.'},
  },
 },
 61: {
  'cards': {
   't61-c4': {'body': 'Storing images as BLOBs in the relational database. At 3 MB a photo, 1M photos is 3 TB inside the tables, every backup and every replica, so restores and new replicas take hours longer. Keep the bytes in object storage and the key, owner and size in a row.'},
  },
  'q': {
   't61-a1': {'prompt': 'A presigned PUT URL for one photo upload ends up in a shared log. What limits the damage?',
    'choices': [('c', 'Only the user who asked for it can use it'), ('d', 'The bucket rejects a second upload to it'), ('b', 'Storage rejects uploads from a new IP'), ('a', 'It expires soon and covers one object key')],
    'correct': 'a',
    'explanation': 'The signature covers the method, the bucket, the object key and an expiry, so a leaked URL can only write that one object until it expires. The app chooses that expiry when signing: minutes is typical (one common SDK defaults to 15), S3 allows up to 7 days, and a URL signed with temporary credentials dies when they do. Anyone holding it can use it, as many times as they like before expiry; storage checks no identity or IP address unless a policy adds conditions.'},
   't61-a3': {'choices': [('d', 'Postgres limits each row to 1 MB of data'), ('a', 'It bloats the database, backups and replicas'), ('b', 'Postgres cannot store binary data in a column'), ('c', 'BLOB columns cannot be backed up or replicated')],
    'correct': 'a',
    'explanation': 'Every image byte then sits in the tables, the backups and each replica, while object storage is cheaper per GB and serves through a CDN. Postgres can store binary data (bytea, up to 1 GB a value) and does back it up and replicate it, which is exactly the cost.'},
   't61-a5': {'explanation': 'A database row (owner, caption, object key, size) is what you filter, join and check permissions on; the object holds only bytes. One bucket per photo runs into account bucket limits, CDN configuration is for routing and caching, and metadata inside the image file cannot be queried.'},
  },
 },
 32: {'q': {
   't32-a1': {'explanation': 'If two sides of a partition both sell the last seat, two fans hold one seat and someone must be refunded and turned away at the gate, so seat inventory should refuse or delay sales until the sides agree. A like count, a view counter or a recommendation that is briefly wrong costs nothing, so those stay available and reconcile later.'},
   't32-a2': {'explanation': 'Networks drop and delay messages whether you plan for it or not, so partition tolerance is not optional, and CAP only forces a choice while a partition lasts: refuse some requests (C) or answer with possibly stale data (A). More replicas mean more links that can be cut, a fast network still partitions, and the theorem applies to any replicated store, SQL or not.'},
   't32-a3': {'explanation': 'In normal operation the system can be both consistent and available. When a partition cuts nodes off, each side must either reject requests it cannot confirm (CP) or serve them with possibly stale data (AP). When the network heals, an AP system reconciles divergent writes; a CP system simply resumes.'},
   't32-a4': {'explanation': 'A like counter that is off by a few for the length of a partition harms nobody, while rejecting likes is visible to every user on the cut-off side. Accepting them and merging later (counters merge by adding) is the right posture; CP would buy exactness nobody needs.'},
   't32-a5': {
     'choices': [('a', 'Reject or delay some requests rather than return stale data'),
                 ('b', 'Return possibly stale data so that each node stays available'),
                 ('c', 'Accept writes on both sides and merge conflicts later'),
                 ('d', 'Let both sides elect a leader so that requests succeed')],
     'correct': 'a',
     'explanation': 'A CP system answers only when it can be sure the answer is current, so the side without a majority refuses or delays requests. Returning stale data and accepting writes on both sides are AP behaviours, and two leaders is split brain, which a CP system prevents with a majority quorum.'},
   't32-d1': {'explanation': 'A node cut off from the ledger leader cannot know the current balance, so a CP design refuses or delays the payment and the client can retry. Approving from a cached balance or approving now and reconciling later risks spending money twice, which is the AP choice, and silently dropping the request is neither: the client must get an answer, even an error.'},
 }},
 69: {'cards': {'t69-c1': {'title': 'Blue-green: two environments, one router switch'}, 't69-c2': {'title': 'Canary: a small share of real traffic first'}}, 'q': {
   't69-a1': {
     'prompt': 'A team ships v2 of the search service. How does a canary release limit the damage if v2 is bad?',
     'choices': [('a', 'Sends a small share of traffic to v2 and compares its error rate'),
                 ('b', 'Switches all traffic at once, then rolls back if many users complain'),
                 ('c', 'Tests v2 only in staging before any user sees it'),
                 ('d', 'Deploys v2 everywhere at night when traffic is lowest')],
     'correct': 'a',
     'explanation': 'A canary gives v2 a small slice of real traffic, say 1%, and compares its errors and latency with v1 over the same minutes, so a bad build hurts few users and is caught by metrics, not complaints. Switching everyone waits for users to notice, staging never sees real traffic, and a night-time deploy still reaches every user at once.'},
   't69-a2': {
     'choices': [('a', 'Point the router back to the old environment'),
                 ('b', 'Redeploy the old build to each server'),
                 ('c', 'Restore the database from last night’s backup'),
                 ('d', 'Keep both live and ship a hotfix to the new one')],
     'correct': 'a',
     'explanation': 'In blue-green the old environment keeps running untouched, so rollback is just switching the router back, usually in seconds. Redeploying the old build is what a rolling update must do, restoring last night’s backup would discard a day of data (and code rollback does not need it), and a hotfix leaves users on the broken version while you write it.'},
   't69-a3': {
     'choices': [('a', 'Flip its kill-switch flag off'),
                 ('b', 'Roll back the whole release everywhere'),
                 ('c', 'Write a hotfix and redeploy it'),
                 ('d', 'Restart every app instance')],
     'correct': 'a',
     'explanation': 'A kill-switch flag turns the widget off within seconds, without a build or a deploy, and leaves the rest of the release in place. A rollback also removes every other change in the release and takes a deploy, a hotfix takes longer still, and restarting instances brings the same crashing widget back.'},
   't69-a4': {'explanation': 'Run v2 beside v1, send it a small share such as 1%, compare its errors and latency with v1 over the same period, and widen in steps (25%, then 100%) only while the numbers hold. Any failed comparison sends the share back to zero.'},
   't69-a5': {'explanation': 'Expand, then contract: add the new column, write both, backfill and switch reads to the new column, and drop the old one only when no running version reads it. At every step both the old and new code work, so a rolling deploy or a canary never breaks.'},
   't69-d1': {'explanation': 'During a canary v1 and v2 run against the same database, so a plain rename breaks whichever version expects the other name. Expand-and-contract keeps both working throughout. Databases can rename columns in place; that is the problem, not the fix. It does not speed up the rollout, and it is independent of whether you use flags.'},
 }},
 57: {'q': {
   't57-a1': {'explanation': 'The agent logged in successfully, so authentication worked; the refund was refused because their role does not cover another region’s orders, which is an authorisation decision. TLS protects the connection, and a rate limit blocks volume, not a single permitted-looking request.'},
   't57-a2': {'explanation': 'A JWT is checked by its signature alone, so once issued it stays valid until it expires, even after logout or a password change. Short lifetimes, refresh tokens or a deny list limit that. JWTs are verified with a public key and no call to the auth server, need no sticky sessions, and can carry plenty of claims.'},
   't57-a3': {'explanation': 'A server-side session is a row in a store, so deleting it ends access on the next request, which matters when a bank must cut off a stolen session at once. Sessions do need storage, usually travel in a cookie, and require each service to look the session up, which is the price of that control.'},
   't57-a4': {'explanation': 'The user logs in (say with an OTP), the server verifies it and issues a short-lived access token (minutes) with a longer-lived refresh token, APIs are called with the access token, and when it expires the client uses the refresh token to get a new one without logging in again.'},
   't57-a5': {'explanation': 'Only the service that owns orders knows whether this user may refund this order, and it must check on every request because roles and ownership change. Hiding the button stops honest users only, a check at login cannot know which order comes later, and a CDN has no view of order ownership.'},
   't57-d1': {'explanation': 'The user really is logged in, so authentication passed; the service never checked that the order belongs to them, which is a broken object-level authorisation check (an insecure direct object reference). TLS and rate limiting are working as designed and do not decide who may see which order.'},
 }},
 52: {'q': {
   't52-a1': {'explanation': 'Instances are created, moved and killed by autoscaling and deploys, so their addresses change all the time; callers need a current list of healthy instances. Encrypting traffic, storing data and versioning APIs are separate concerns handled by TLS, databases and API design.'},
   't52-a2': {
     'choices': [('a', 'Its heartbeats stop and its entry expires'),
                 ('b', 'The crashed instance sends a final message'),
                 ('c', 'The next deploy rebuilds the registry'),
                 ('d', 'Callers report it after their first failed call')],
     'correct': 'a',
     'explanation': 'A registry keeps an entry only while the instance renews it with heartbeats (or passes health checks), so a crashed instance’s entry lapses after a few missed intervals. A crashed process cannot send a goodbye, waiting for the next deploy could take days, and callers do not normally write to the registry; they retry another instance.'},
   't52-a3': {'explanation': 'In server-side discovery the caller sends to one stable address and a load balancer or proxy picks a healthy instance. Querying a registry such as Consul and choosing yourself is client-side discovery, a config file of IPs is static configuration, and broadcasting addresses to every caller does not scale.'},
   't52-a4': {'explanation': 'An instance registers when it starts and keeps renewing with heartbeats; a caller looks the service up, gets the healthy instances and calls one, usually caching the list briefly. Registration must come first, or there is nothing to find.'},
   't52-a5': {'explanation': 'A Service gives a set of pods one stable DNS name and virtual IP and keeps its endpoint list in step with the pods that pass readiness. A ConfigMap would need editing on every pod change, a replica count says how many pods exist, not where, and a liveness probe restarts pods without routing anything.'},
   't52-d1': {'explanation': '5 s × 3 failures ≈ 15 s, and during that window calls to the dead instance fail, so callers need retries to another instance. Faster checks shorten the window but risk marking slow instances dead.'},
 }},
 62: {'q': {
   't62-a1': {'explanation': 'A rack shares a power feed and a top-of-rack switch, so losing it takes every copy on it. HDFS’s default policy puts the first replica on the writer’s node and the other two on two nodes of a different rack, so a rack failure always leaves a copy. Cross-rack copies make writes slower, not faster, use the same storage, and racks hold many DataNodes.'},
   't62-a2': {'explanation': 'Every file and block costs about 150 bytes of NameNode memory, so millions of tiny files exhaust it, and HDFS is built for streaming big files, not millisecond lookups. Nightly scans of 50 TB, large Parquet files and raw clickstream archives are exactly what it is built for.'},
   't62-a3': {'explanation': 'The client asks the NameNode which DataNodes hold each block, then streams the blocks directly from those DataNodes, preferring the nearest. File data never passes through the NameNode, which is why one NameNode can serve a large cluster.'},
   't62-a4': {'explanation': 'The NameNode holds the namespace in memory: directories, files, their blocks and where each block’s replicas live. The block data itself sits on DataNodes, user credentials come from Kerberos or another system, and it tracks every block, not only new ones.'},
   't62-d1': {'explanation': '1,048,576 MB ÷ 128 MB = 8,192 blocks, and with replication factor 3 the cluster stores 24,576 block replicas. 1,024 would be 1 GB blocks, 128 is the block size itself, and 24,576 counts replicas, not blocks.'},
 }},
 54: {'q': {
   't54-a2': {
     'prompt': 'The checkout service’s dashboard must show its health at a glance using the RED method. Which three numbers does it show?',
     'choices': [('a', 'Rate, errors and duration of requests'),
                 ('b', 'Requests, events and disk use'),
                 ('c', 'Reads, edits and deletes per table'),
                 ('d', 'Retries, exceptions and deploys per day')],
     'correct': 'a',
     'explanation': 'RED tracks what callers see: request rate, the share that fail, and how long they take (as percentiles such as p99). Disk use belongs to USE, which covers resources. Per-table reads and edits, and counts of deploys or retries, are useful elsewhere but do not say whether checkout is healthy.'},
   't54-a3': {'explanation': 'USE describes resources: utilisation, saturation and errors. The disk’s I/O queue depth is saturation, work waiting because the disk is busy. API request rate and p99 latency are RED signals for a service, and deploys are events, not a resource measure.'},
   't54-a4': {'explanation': 'The first service gives the request a trace id and passes it on every call; each service logs with it and records spans; metrics are aggregated from the same events; dashboards and alerts read the metrics, and a slow request can be followed from an alert to its trace and logs.'},
   't54-a5': {
     'choices': [('a', 'Huge volume and cost, and hard to query'),
                 ('b', 'Requests slow down because logging blocks'),
                 ('c', 'Traces lose their spans under the load'),
                 ('d', 'Metrics get less accurate as logs grow')],
     'correct': 'a',
     'explanation': 'DEBUG in production multiplies log volume, and storage and indexing bills, while free text cannot be filtered reliably by field. Use structured logs at INFO, with sampling for chatty paths. Logging can slow requests if writes are synchronous, but the main problem here is cost and queryability; traces and metrics are separate pipelines.'},
   't54-d1': {
     'choices': [('a', 'A distributed trace of that request'),
                 ('b', 'The payment service’s CPU metric'),
                 ('c', 'The payment service’s p99 latency'),
                 ('d', 'The payment service’s error log')],
     'correct': 'a',
     'explanation': 'A trace records each service’s span with its start and duration under one trace id, so it shows that this request spent 3.2 s in payments. A p99 latency or CPU chart summarises many requests and cannot point to this one, and an error log shows nothing if the call was slow but succeeded.'},
 }},
 28: {'q': {
   't28-a1': {'explanation': 'The write reached the leader, but the refresh was read from a replica that had not applied it yet: replication lag. Read-your-writes fixes it, by reading from the leader for a short while after a user writes, or from a replica known to have caught up. A constraint failure would have returned an error, a lost write would not reappear seconds later, and session expiry logs the user out rather than hiding a review.'},
   't28-a2': {'explanation': 'The leader acknowledges before replicas have the change, so if it dies, writes in flight (often under a second’s worth) are lost on failover. Waiting for replicas is synchronous replication, replicas still serve reads, and split brain comes from a bad failover, not from each write.'},
   't28-a3': {'explanation': 'Two leaders can accept writes to the same row at the same moment, so the system needs a rule to resolve the conflict: last write wins, merging, or asking the user. Multi-leader avoids a global lock, replicas still serve reads, and lag gets worse, not impossible.'},
   't28-a4': {'explanation': 'The client writes to the leader, which records the change in its log, ships the log to the replicas, and each replica applies it in order. Reads from replicas see the change only after it is applied, which is the replication lag.'},
   't28-a5': {'explanation': 'Synchronous replication makes each commit wait for the replica in the other zone, a few milliseconds, so a failover loses no acknowledged payment. Asynchronous replication is faster but can lose the last moments of payments when the leader dies.'},
   't28-d1': {'explanation': '2,000 writes/s × 0.3 s of lag ≈ 600 writes acknowledged but not yet on the replica. None would need synchronous replication, 6 and 2,000,000 are off by factors of 100 and 3,000.'},
 }},
 8: {'q': {
   't8-a1': {'explanation': 'PUT replaces the resource at a known URL with the full order, so sending it twice leaves the same state. POST asks the server to create something, so a retry can create a second order or a second item unless the API accepts an idempotency key.'},
   't8-a2': {'explanation': '201 Created with a Location header tells the client the order exists and where it lives. 200 with an error field hides the outcome in the body, 204 gives the client no id to use, and a 302 is for browsers navigating, not an API reporting creation.'},
   't8-a3': {'explanation': 'REST names resources in the path and uses the HTTP method as the verb, so fetching order 42 is GET /v1/orders/42. Verbs in the path (getOrder, fetch, delete) duplicate the method, and a GET that deletes breaks caches and crawlers that assume GET is safe.'},
   't8-a4': {'explanation': 'A cursor says “after this id”, so new orders arriving at the top do not shift the pages, and the database seeks straight to the position. Page 2,500 with an offset reads and discards 49,980 rows and shows duplicates or gaps as rows arrive. Returning all 50,000 is slow and heavy, and only the newest 20 hides the rest of the history.'},
   't8-a5': {'explanation': 'The client sends POST /v1/orders, the server validates the body before touching the database, creates the order, and returns 201 Created with the new order’s Location. Validating first means a bad request costs nothing and leaves no half-made order.'},
 }},
 67: {'q': {
   't67-a1': {
     'choices': [('a', 'A restaurant 50 m away can sit just across the boundary'),
                 ('b', 'Neighbouring cells are usually already in the cache'),
                 ('c', 'Geohash cells overlap, so points appear in several'),
                 ('d', 'Searching nine cells spreads the load across shards')],
     'correct': 'a',
     'explanation': 'Cell boundaries are arbitrary lines, so a restaurant 50 m away can fall in the next cell with a different prefix. Searching the user’s cell and its 8 neighbours covers that, then exact distance filters the candidates. Geohash cells tile the map without overlap, caching is not the reason, and the search is about correctness, not load.'},
   't67-a2': {'explanation': 'A quadtree splits a cell only where it holds too many points, so cells are tiny in Mumbai and huge over the Thar desert, and every query sees a similar number of candidates. A fixed grid gives either crowded cells in cities or millions of empty ones. Quadtrees need extra memory for their nodes, give straight-line not road distances, and grids store both coordinates.'},
   't67-a3': {'explanation': 'Find the user’s cell at a size near 2 km, add its 8 neighbours so boundary cases are covered, fetch the candidates in those cells, then compute exact distances, drop anything beyond 2 km and sort.'},
   't67-a4': {'explanation': 'Each geohash character narrows the cell, so a long shared prefix means both points sit in the same small cell and are close. The reverse does not hold: two points either side of a cell edge can be metres apart with different prefixes, which is why searches add neighbouring cells. Prefixes say nothing about direction and are not random.'},
   't67-a5': {'explanation': 'An index that splits space so each query reads only nearby cells keeps lookups local whether the city is dense or sparse. Large fixed cells return thousands of candidates in Mumbai, and scanning every restaurant reads millions of rows for each search.'},
   't67-d1': {'explanation': 'Close points can sit across a cell boundary and have different prefixes, so the 8 neighbours cover them; exact distance then filters the candidates. Reading nine cells makes queries bigger, not the index smaller, geohashes work alone as cells, and distances are still computed.'},
 }},
 44: {'q': {
   't44-a1': {
     'choices': [('a', 'The order exists but no event was published'),
                 ('b', 'Kafka rolls the order back on its own'),
                 ('c', 'The event is sent, but the order is lost'),
                 ('d', 'Both the order and the event are lost')],
     'correct': 'a',
     'explanation': 'The database commit finished before the crash and the publish never ran, so the order exists but downstream services never hear of it. Two separate systems are written separately, with nothing to make them atomic. Kafka knows nothing about the order, and the order was committed first, so it survives.'},
   't44-a2': {'explanation': 'The event goes into an outbox table in the same local transaction as the order, so both commit or neither does; a relay then publishes outbox rows and marks them sent. Publishing first just reverses the failure, two-phase commit between a database and Kafka is rarely available and slow, and retrying from memory loses the event if the process dies.'},
   't44-a3': {'explanation': 'BEGIN, insert the order and its outbox event, COMMIT; only after the commit does the relay read unsent rows, publish them and mark them sent. A crash between publish and marking republishes, so delivery is at least once.'},
   't44-a4': {'explanation': 'Change data capture tails the database’s own change log (the PostgreSQL WAL or MySQL binlog), which already holds every committed change in order. Polling with SELECT * misses intermediate updates and loads the database, intercepting HTTP misses changes made any other way, and relying on developers to publish is the dual write again.'},
   't44-a5': {
     'choices': [('a', 'It republishes, so consumers must be idempotent'),
                 ('b', 'The event is lost and must be sent by hand'),
                 ('c', 'The database rolls back the original order'),
                 ('d', 'Kafka drops the duplicate before consumers see it')],
     'correct': 'a',
     'explanation': 'The row is still unmarked, so the restarted relay publishes it again and consumers see the event twice. That is at-least-once delivery, so consumers deduplicate by event id. Nothing is lost, the order committed long ago, and an idempotent Kafka producer deduplicates retries within one producer session, not a republish from a new process.'},
   't44-d1': {
     'choices': [('a', 'Write the event to an outbox table in the same transaction'),
                 ('b', 'Publish the event first, then update the database'),
                 ('c', 'Retry the publish in memory until Kafka accepts it'),
                 ('d', 'Wrap the database write and the publish in a try block')],
     'correct': 'a',
     'explanation': 'The outbox makes the event part of the same atomic commit as the update, and a relay publishes it afterwards. Publishing first fails the other way, an event for an update that never happened. In-memory retries and try blocks die with the process, which is the failure in question.'},
 }},
 118: {'q': {
   't118-a1': {'explanation': 'Good narration states a decision and the reason that drives it, ideally with a number, so the interviewer can follow and challenge it. Describing boxes says what, not why, and “Netflix does it” or “everyone uses Redis” borrow a reason that may not fit these requirements.'},
   't118-a2': {'explanation': 'Saying you have not used it, then naming what you need (say, durable writes at 5,000/s and range queries by time), shows reasoning the interviewer can map onto that database. Bluffing collapses under one follow-up question, refusing ignores their lead, and changing the subject looks evasive.'},
   't118-a3': {'explanation': 'A thousand users fit on one server and one database, so start there and add parts only when a number demands them. Multi-region, microservices with Kafka and sharding solve problems these users do not have, and each adds cost you would have to justify.'},
   't118-a4': {'explanation': 'Start with one server; add a load balancer and stateless app servers when one machine is not enough; add a cache and CDN when reads dominate; add read replicas when the database is read-bound; shard and go multi-region last, when writes or geography demand it.'},
   't118-d1': {'explanation': 'A simple design that already works gives every later addition a reason: the cache appears because reads are 100× writes, the shard because writes exceed one machine. Diagram size is not the point, complex designs can be right when the numbers call for them, and the step-by-step approach invites trade-off discussion rather than avoiding it.'},
 }},
 60: {'q': {
   't60-a1': {'explanation': 'A parameterised query sends the SQL and the input separately, so the input is always treated as data and can never change the query. Stripping quotes misses other encodings and breaks names like O’Brien, hiding errors only hides the evidence, and a stored procedure that concatenates the same string is just as injectable.'},
   't60-a2': {'explanation': 'A secrets manager stores the key encrypted, controls who can read it, logs each access and supports rotation; the app fetches it at runtime. A private repository, a Docker image and a mobile app are all copied widely, so anyone with a copy has the key, and obfuscation in an app can be reversed in minutes.'},
   't60-a3': {'explanation': 'A reporting service that only reads should have read access only to the tables it uses, so stolen credentials cannot change or delete orders. The admin account, spare write access or the checkout account all hand an attacker far more than reporting needs.'},
   't60-a4': {'explanation': 'TLS at the edge protects the connection, rate limits and a firewall shed abusive traffic cheaply, authentication establishes who is calling, authorisation decides what they may do, and validation with parameterised queries keeps their input from turning into code. Each layer stops something the earlier ones let through.'},
   't60-a5': {'explanation': 'TLS protects data in transit and nothing else. An attacker can still call the API over HTTPS with a stolen token, someone else’s order id or an injection payload, so authentication, authorisation, input validation and rate limits are all still needed. Certificates and a CDN firewall do not change that.'},
   't60-d1': {
     'prompt': 'A dashboard’s database password leaks in a public log. That account was granted SELECT on three tables only. How far can whoever finds it get?',
     'choices': [('a', 'Read those three tables, and nothing else'),
                 ('b', 'Read and change every table in the database'),
                 ('c', 'Read the three tables and drop them'),
                 ('d', 'Nothing, because the reads are encrypted')],
     'correct': 'a',
     'explanation': 'That is least privilege at work: the stolen account can read three tables, a real leak but a bounded one, and cannot change, drop or reach anything else. Encryption in transit does not stop someone holding valid credentials from reading.'},
 }},
 23: {'q': {
   't23-a1': {'explanation': 'A composite index is sorted by city first, then created_at within each city, so city = \'Pune\' jumps to Pune and the date range scans a contiguous slice. A filter on created_at alone or on status cannot use the sort order, and the OR needs rows that match either condition, which one composite index cannot serve on its own.'},
   't23-a2': {'explanation': 'Each index is another sorted structure, so every insert, and every update of an indexed column, writes to all five, adding latency, WAL and storage. Planning gets slightly harder but that is minor, indexes do not prevent sharding, and the cost continues for as long as they exist.'},
   't23-a3': {'explanation': 'An LSM-tree buffers writes in memory and flushes them as sorted files, so heavy write streams such as event logs become sequential appends. Reads can touch several files, so mostly-read data, small in-memory tables and complex joins favour a B-tree database.'},
   't23-a4': {'explanation': 'A query filters on a column, and without an index the database scans every row. A B-tree on that column makes lookups take a few page reads (log time), and from then on every write also updates the index: faster reads, paid for by writes.'},
   't23-d1': {'explanation': '200 keys a page gives 200, 40,000, 8 million and 1.6 billion entries for one to four levels, so 500 million needs four. Two levels hold only 40,000, nine would need a far smaller fan-out, and 500 levels would be a list, not a tree.'},
 }},
 16: {'q': {
   't16-a1': {'explanation': 'Write-behind acknowledges once the cache has the write and flushes to the database later, so a cache crash loses whatever has not been flushed. Write-through writes the database before replying, and cache-aside writes the database directly, with or without a short TTL, so the cache holds only copies.'},
   't16-a2': {'explanation': 'Write-through updates the database and the cache on every write before replying, so reads usually see fresh data; races between concurrent writers or a failure between the two updates can still leave a stale entry, so keep a TTL. The cost is two writes on each request. Buffered writes are write-behind, writing only to the cache skips durability, and new keys can still miss.'},
   't16-a3': {'explanation': 'The app reads the cache, misses, reads the database, sets the value in the cache with a TTL and returns it. The application, not the cache, loads data, so the cache can be a plain key-value store, and the TTL bounds how long a stale copy can survive.'},
   't16-a4': {'explanation': 'Reads outnumber writes 100 to 1 and a few seconds of staleness is fine, so cache-aside with a TTL serves almost every read from memory while the database stays the source of truth. Write-through adds work to every write for freshness nobody needs, and write-behind risks losing catalogue edits.'},
   't16-a5': {'explanation': 'Write-behind acknowledges before the database has the write, so a cache crash can lose ledger entries that users were told succeeded. Reads do not wait for flushes, the cache remains useful for reads, and there is no blanket rule against storing payment data in Redis; the problem is durability.'},
   't16-d1': {'explanation': '20,000 likes/s × 5 s ≈ 100,000 likes unflushed in the worst case. 20,000 is only one second, 4,000 is a fifth of a second, and none would require the writes to reach the database before acknowledging.'},
 }},
 3: {'q': {
   't3-a2': {'explanation': 'A bigger machine is simple, but the largest instance is a hard ceiling and it is still one machine whose failure takes the service down. Bigger machines add memory and disk too, load balancers route to any size, and the app does not have to change to run on a larger box.'},
   't3-a3': {'explanation': 'Four app servers mean one can fail while the others carry the load, so that tier is far more available. Every request still needs the one primary database, so its failure stops everything. Availability does not multiply by the server count, and round robin alone sends traffic to dead servers unless health checks remove them.'},
 }},
 33: {'q': {
   't33-a1': {'explanation': 'CAP covers only partitions. PACELC adds the everyday case: even with a healthy network, waiting for replicas to agree costs latency, so a system picks low latency (L) or consistency (C). It does not add a third partition choice, avoid partitions, or say anything about durability.'},
   't33-a2': {'explanation': 'With default settings (for example consistency level ONE) Cassandra keeps serving during a partition and answers from the nearest replica normally, so it is usually labelled PA/EL. Higher consistency levels such as QUORUM move individual requests towards C at the cost of latency.'},
   't33-a3': {'explanation': 'A product description a few seconds old harms nobody, so the local replica answers in milliseconds. Reading from a leader in another region, or a quorum across three regions, adds tens to hundreds of milliseconds per read for freshness nobody notices, and blocking until replication is idle could wait forever on a busy system.'},
   't33-a5': {'explanation': 'The same read, a price from Mumbai, can go to the local replica (fast, maybe stale) or the leader in Singapore (slower, fresh). The right choice depends on the feature: browsing takes the local replica, checkout takes the leader.'},
   't33-d1': {
     'choices': [('a', 'EC: it chooses consistency over latency in the else case'),
                 ('b', 'EL: it chooses latency in the else case'),
                 ('c', 'PA: it chooses availability during a partition'),
                 ('d', 'PC/EL: consistent only while partitioned')],
     'correct': 'a',
     'explanation': 'Waiting for a cross-region majority when nothing is wrong spends latency to stay consistent, which is EC. EL would answer before replicas agree, and the question says nothing about behaviour during a partition, so PA and PC labels are guesses; PC/EL would also contradict the waiting it does every day.'},
 }},
 70: {'q': {
   't70-a1': {'explanation': 'A failed liveness probe restarts the container, so if it checks the database, a database blip restarts every pod at once and they loop. Dependency checks belong in readiness, which only stops traffic to the pod until the database is back. Image size and rollout speed do not cause synchronised restarts.'},
   't70-a2': {'explanation': 'Once the node is marked unreachable, its pods are evicted after a grace period (300 s by default), and the controller that owns them creates replacements on healthy nodes. Kubernetes cannot restart a dead machine, does not wait indefinitely, and does not move traffic to another cluster on its own. Run spare replicas across nodes so those minutes do not matter.'},
   't70-a3': {'explanation': 'After the new image is pushed, the Deployment creates a new pod, waits for its readiness probe to pass, lets the Service send it traffic, and only then removes one old pod; it repeats until all pods are new. Removing an old pod first would cut capacity during the deploy.'},
   't70-a4': {'explanation': 'A container is an isolated process on the host’s already-running kernel, so starting it is like starting a program, while a VM must boot a whole guest operating system. Containers do have a network stack and a filesystem, and they run on VMs as well as bare metal.'},
   't70-a5': {'explanation': 'The Deployment’s controller continually compares the declared 5 replicas with what is running, sees 4 and starts a fifth. Nobody needs to reapply anything, the other pods are left alone, and the Deployment itself is not deleted.'},
   't70-d1': {'explanation': 'A failing readiness probe removes the pod from the Service’s endpoints, so it gets no traffic until the cache is warm, without restarting it. A liveness probe would restart it, possibly before it ever finishes loading; Kubernetes cannot guess when an app is ready, and the autoscaler changes the replica count, not routing.'},
 }},
 14: {'q': {
   't14-a1': {'explanation': 'With carts in each server’s memory, a request that lands on the other server finds no cart. Move carts to a shared store or the database. Databases handle two servers easily, a balancer that strips cookies breaks every login, not only carts, and round robin spreads requests rather than concentrating them.'},
   't14-a2': {'explanation': 'Pinning users to instances spreads load unevenly when some users are heavy, and when an instance dies or is redeployed its users lose their sessions. Sticky sessions add no extra round trip, work alongside health checks, and need a cookie rather than a JWT.'},
   't14-a3': {'explanation': 'If session state lives in a shared store such as Redis, or in a signed token the client sends back, any instance can serve any request and instances can be replaced freely. In-memory state without stickiness loses sessions on every hop, a load balancer is not a session store, and local disk files are just as tied to one server.'},
   't14-a4': {'explanation': 'The client sends its session cookie, the balancer picks any instance, the instance loads the session from Redis, handles the request and writes any changes back. Nothing stays on the instance between requests, so it can be replaced at any time.'},
   't14-a5': {'explanation': 'Rolling deploys restart instances every day, so sticky sessions would log users out on each restart and skew load towards long-lived instances. A Redis session store keeps instances disposable and lets the balancer spread traffic evenly, for about a millisecond per request to fetch the session.'},
 }},
 7: {'q': {
   't7-a1': {'explanation': 'A layer-7 balancer routes on the HTTP path, which it can read only after decrypting, so TLS terminates there (or at the edge in front of it), with re-encryption or mTLS to the services if needed. Terminating only at backends hides the path, databases do not speak HTTP, and dropping TLS anywhere exposes traffic to anyone on that network.'},
   't7-a2': {'explanation': 'TLS encrypts and protects the connection and proves the server’s identity. It does not say who the user is, does not stop SQL injection (the server decrypts the payload and runs it), and says nothing about data at rest in the database or backups.'},
   't7-a5': {'explanation': 'A trusted certificate authority vouched that the key in the certificate belongs to that domain, and the handshake proves the server holds the matching private key, so the browser knows it reached the real site and not an impostor. A certificate makes nothing faster, says nothing about the server’s code, and does not log the user in.'},
   't7-d1': {'explanation': 'An attacker who records 0-RTT early data can resend it, and the server cannot tell the copy from the original, so a payment could run twice. Early data is encrypted, runs over TCP as well as QUIC, and certificates are still checked, so only replay is the problem; send only idempotent requests as early data.'},
 }},
 25: {'cards': {'t25-c4': {'title': 'Durability: the log reaches disk before commit returns'}}},
 53: {'cards': {'t53-c1': {'title': 'Timeouts shorter than the caller’s deadline'},
                't53-c2': {'title': 'Retries: few, idempotent, with backoff and jitter'},
                't53-c5': {'title': 'Bulkheads: a separate pool per dependency'}}},
}
